//! Message queue: actor/mailbox model per session with multiple queue modes.

use std::collections::{HashMap, VecDeque};
use std::sync::Arc;

use serde::{Deserialize, Serialize};
use tokio::sync::{Mutex, RwLock, mpsc};

use layers_core::InboundMessage;

// ---------------------------------------------------------------------------
// Queue modes
// ---------------------------------------------------------------------------

/// How queued messages are handled when a run is already active.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, Default)]
pub enum QueueMode {
    /// Coalesce queued messages into a follow-up turn after current run finishes.
    #[default]
    Collect,
    /// Inject into current run at the next tool boundary.
    Steer,
    /// Enqueue for the next turn (no coalescing).
    Followup,
    /// Abort active run, run newest message immediately.
    Interrupt,
    /// Steer the current message + preserve backlog for followup.
    SteerBacklog,
}

// ---------------------------------------------------------------------------
// Queued entry
// ---------------------------------------------------------------------------

/// A message waiting in the session queue.
#[derive(Debug, Clone)]
pub struct QueuedMessage {
    pub message: InboundMessage,
    pub mode: QueueMode,
    pub queued_at: chrono::DateTime<chrono::Utc>,
}

// ---------------------------------------------------------------------------
// Session queue (per-session mailbox)
// ---------------------------------------------------------------------------

/// Per-session mailbox that serializes runs and queues concurrent messages.
pub struct SessionQueue {
    /// Pending messages waiting for the next run.
    pending: Mutex<VecDeque<QueuedMessage>>,
    /// Whether a run is currently active for this session.
    active_run: Mutex<bool>,
    /// Default queue mode for this session.
    default_mode: QueueMode,
    /// Channel to notify when a queued message should steer the active run.
    steer_tx: Option<mpsc::Sender<QueuedMessage>>,
}

impl SessionQueue {
    pub fn new(default_mode: QueueMode) -> Self {
        Self {
            pending: Mutex::new(VecDeque::new()),
            active_run: Mutex::new(false),
            default_mode,
            steer_tx: None,
        }
    }

    /// Create a queue with a steer channel for injecting messages into active runs.
    pub fn with_steer_channel(default_mode: QueueMode) -> (Self, mpsc::Receiver<QueuedMessage>) {
        let (tx, rx) = mpsc::channel(64);
        let queue = Self {
            pending: Mutex::new(VecDeque::new()),
            active_run: Mutex::new(false),
            default_mode,
            steer_tx: Some(tx),
        };
        (queue, rx)
    }

//! The main agent loop: intake → context → inference → tool exec → persist → loop.

use std::sync::Arc;
use std::time::Duration;

use chrono::{DateTime, Utc};
use serde::{Deserialize, Serialize};
use tokio_util::sync::CancellationToken;
use tracing::warn;

use layers_core::{
    LayersError, Message, MessageContent, MessageRole, ModelProvider, ModelRef, ModelRequest,
    Result, Session, SessionStore, TokenBudget, ToolContext,
};

use crate::context::ContextAssembler;
use crate::failover::FailoverChain;
use crate::streaming::{StreamEvent, StreamSink};
use crate::system_prompt::SystemPromptBuilder;
use crate::tool_dispatch::ToolRegistry;

// ---------------------------------------------------------------------------
// Agent run configuration
// ---------------------------------------------------------------------------

/// Configurable limits for an agent run.
#[derive(Debug, Clone)]
pub struct RunConfig {
    /// Maximum tool-loop iterations before aborting. Default: 50.
    pub max_tool_iterations: usize,
    /// Overall run timeout. Default: 48 hours.
    pub run_timeout: Duration,
    /// LLM idle timeout (time waiting for model response). Default: 60s.
    pub llm_idle_timeout: Duration,
    /// How many times the same (tool, args) pair can repeat. Default: 3.
    pub repeat_threshold: usize,
}

impl Default for RunConfig {
    fn default() -> Self {
        Self {
            max_tool_iterations: 50,
            run_timeout: Duration::from_secs(48 * 3600),
            llm_idle_timeout: Duration::from_secs(60),
            repeat_threshold: 3,
        }
    }
}

// ---------------------------------------------------------------------------
// Run status
// ---------------------------------------------------------------------------

/// Current status of an agent run.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub enum RunStatus {
    /// Waiting for input.
    Idle,
    /// Processing: running inference or tool execution.
    Running,
    /// Completed normally.
    Completed,
    /// Cancelled by user or parent.
    Cancelled,
    /// Failed with error.
    Failed(String),
}

// ---------------------------------------------------------------------------
// AgentRun — tracks a single run
// ---------------------------------------------------------------------------

/// Tracks the state of one serialized run within a session.
pub struct AgentRun {
    pub session_key: String,
    pub model_ref: ModelRef,
    pub cancel: CancellationToken,
    pub status: RunStatus,
    pub started_at: DateTime<Utc>,
    pub tool_iterations: usize,

//! Critical-path routing V1.
//!
//! Implements weighted fair queueing with a reserved worker slot for
//! critical-path tasks.  A task is `critical_path=true` iff it sits on
//! the synchronous return path of a user-initiated prompt and the caller
//! awaits the result before replying.
//!
//! Council decisions baked in:
//! - 8:1 weighted dequeue ratio (critical : standard).
//! - 1 reserved worker slot for the critical queue.
//! - Bounded critical-queue depth with back-pressure.
//! - Synchronous sub-tasks inherit `critical_path=true`; async/background
//!   side-effects default to `false`.
//! - Missing flags default to `false` for backward compatibility.

use std::collections::VecDeque;
use std::sync::{Arc, Condvar, Mutex, OnceLock};
use std::time::Instant;

use serde::{Deserialize, Serialize};

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

/// Critical queue dequeues per scheduling round.
const CRITICAL_WEIGHT: usize = 8;
/// Standard queue dequeues per scheduling round.
const STANDARD_WEIGHT: usize = 1;
/// Default maximum depth for the critical queue before back-pressure kicks in.
const DEFAULT_CRITICAL_QUEUE_CAPACITY: usize = 64;
/// Default total worker count (including the reserved critical slot).
const DEFAULT_TOTAL_WORKERS: usize = 4;
/// The number of worker slots permanently reserved for critical work.
const RESERVED_CRITICAL_SLOTS: usize = 1;

// ---------------------------------------------------------------------------
// Classification helper
// ---------------------------------------------------------------------------

/// Returns `true` when the task sits on the synchronous return path of a
/// user-initiated prompt and the caller awaits the result before replying.
///
/// The function inspects the envelope flag first (explicit caller intent),
/// then falls back to heuristic detection based on the `route` string and
/// whether there is a parent task flagged as critical.
pub fn is_critical_path(explicit_flag: Option<bool>, route: &str, parent_critical: bool) -> bool {
    // 1. Explicit flag takes precedence (caller opted in/out).
    if let Some(flag) = explicit_flag {
        return flag;
    }

    // 2. Synchronous sub-tasks inherit from parent.
    if parent_critical {
        return true;
    }

    // 3. Routes that sit on the synchronous user-reply path.
    matches!(
        route,
        "direct" | "council_only" | "both" | "memory_only" | "graph_only"
    )
}

/// Determine whether a sub-task should inherit the critical-path flag.
///
/// - Synchronous children: inherit `true` from a critical parent.
/// - Async / background side-effects: always `false`.
pub fn inherit_critical_path(parent_critical: bool, is_sync: bool) -> bool {
    if is_sync { parent_critical } else { false }
}

